import type { ApiResult } from './api.ts';
type Lab = { code: string };
export function labName(r: ApiResult<Lab>): string {
  // Reading data without narrowing on ok.
  return r.data.code;
}

export type ApiOk<T> = { ok: true; data: T };
export type ApiErr = { ok: false; error: { code: string; message: string } };
export type ApiResult<T> = ApiOk<T> | ApiErr;

import { labName } from '../src/read.ts';
const s: string = labName({ ok: true, data: { code: 'BE-201' } });
export { s };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { labName } from '../src/read.ts';
test('labName', () => { assert.equal(labName({ ok: true, data: { code: 'BE-201' } }), 'BE-201'); assert.equal(labName({ ok: false, error: { code: 'X', message: 'bad' } }), 'bad'); });

