import type { ApiResult } from './api.ts';
type Lab = { code: string };
export function notFound(): ApiResult<Lab> {
  // Wrong: error must be an object with code and message.
  return { ok: false, error: 'not found' };
}

export type ApiOk<T> = { ok: true; data: T };
export type ApiErr = { ok: false; error: { code: string; message: string } };
export type ApiResult<T> = ApiOk<T> | ApiErr;

import { notFound } from '../src/err.ts';
const r = notFound();
const msg: string = r.ok ? 'ok' : r.error.message;
export { msg };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { notFound } from '../src/err.ts';
test('notFound', () => { const r = notFound(); assert.equal(r.ok, false); if (!r.ok) assert.equal(r.error.code, 'NOT_FOUND'); });

